      items.push({ z: sl.x + sl.y + S + (it.wide ? 2.4 : 0), s: '<g class="tp-item" data-slot="' + k + '">' + egg(id, at(sl.x, sl.y, 0, it.draw(so)), it.bits ? at(sl.x, sl.y, 0, it.bits(so)) : "") + "</g>" });
