      [[22, 26, 5, 0], [w - 24, 30, 4, .6], [26, h * .62, 3.6, 1.2], [w - 22, h * .6, 4.6, .3], [cx - 36, cy - 30, 3, 1.6], [cx + 38, cy - 22, 3.4, .9]].forEach(function(q){ s += dmStar(q[0], q[1], q[2], q[3] > 1 ? "#FFFFFF" : K.dmLight, "tp-r-tw", q[3]); });
