    var d = "M" + f(x) + " " + f(by) + " V" + f(cy), s = L(d, birch ? 5 : 4.6) + L(d, birch ? 3 : 2.6, birch ? (night ? "#B9B4C4" : "#FFFDF6") : (night ? "#5E4C48" : "#8A5A3A"));
    if (birch) s += L("M" + f(x - 1.4) + " " + f(by - 5) + " h2 M" + f(x - .4) + " " + f(by - 10) + " h1.8", .9);
