        s += L("M" + q(-15, 11) + " C" + q(-27, -10) + " " + q(-28, -34) + " " + q(-21, -50), .9, nut.s, .8) + L("M" + q(-3, 14) + " C" + q(-8, -6) + " " + q(-8, -26) + " " + q(-5, -36), .9, nut.s, .6) + T.HI("M" + q(-34, -34) + " Q" + q(-37, -21) + " " + q(-32, -8), 2);
