        /* the pile */
        var d = "M" + f(x - 27) + " " + f(y + 2) + " q-2 -10 6 -14 q2 -8 12 -9 q6 -6 14 -1 q10 0 13 9 q8 4 6 13 q-12 9 -27 8 q-15 0 -24 -6 z";
